-- Protocol tests against vectors generated by tinytuya (tools/gen-test-vectors.py).

package.path = "src/?.lua;test/?.lua;test/support/?.lua;" .. package.path
local H = require("support.harness")
local crypto = require("tuya.crypto")
local F = require("tuya.frame55")
local P = require("tuya.payload")
local v33 = require("tuya.v33")
local v34 = require("tuya.v34")
local v35 = require("tuya.v35")
local fake = require("support.fake_device")
local X = fake.X

local function reader(bytes)
  local buf = bytes
  local sent = {}
  local seq = 1
  return {
    recv = function(n)
      if #buf < n then return nil, "timeout" end
      local out = buf:sub(1, n)
      buf = buf:sub(n + 1)
      return out
    end,
    send = function(b) sent[#sent + 1] = b return #b end,
    next_seq = function() seq = seq + 1 return seq - 1 end,
    sent = sent,
  }
end

-- Crypto primitives ----------------------------------------------------------

H.test("sha256 known answer", function()
  H.eq(crypto.hex(crypto.sha256("abc")), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
end)

H.test("hmac-sha256 RFC 4231 case 2", function()
  H.eq(crypto.hex(crypto.hmac_sha256("Jefe", "what do ya want for nothing?")),
    "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843")
end)

H.test("AES-128-ECB FIPS-197 known answer, and round trip", function()
  local key = crypto.unhex("000102030405060708090a0b0c0d0e0f")
  local pt = crypto.unhex("00112233445566778899aabbccddeeff")
  local ct = crypto.ecb_encrypt(key, pt, false)
  H.eq(crypto.hex(ct), "69c4e0d86a7b0430d8cdb78070b4c55a")
  H.eq(crypto.ecb_decrypt(key, crypto.ecb_encrypt(key, "hello tuya")), "hello tuya")
end)

H.test("ECB decrypt rejects partial blocks", function()
  local text, err = crypto.ecb_decrypt(X.local_key, "short")
  H.eq(text, nil)
  H.truthy(err:find("multiple of 16"))
end)

-- 3.3 ------------------------------------------------------------------------

H.test("3.3 control frame matches tinytuya byte for byte", function()
  H.eq(v33.encode(P.COMMAND.CONTROL, 1, X.v33_control_plain, X.local_key), X.v33_control)
end)

H.test("3.3 query frame has no version header and matches tinytuya", function()
  H.eq(v33.encode(P.COMMAND.DP_QUERY, 2, X.v33_query_plain, X.local_key), X.v33_query)
end)

H.test("3.3 decodes replies with and without the clear version header", function()
  for _, name in ipairs({"v33_reply_header", "v33_reply_plain"}) do
    local reply = assert(v33.read(reader(X[name]), X.local_key))
    H.eq(reply.text, X.status_json, name)
    H.eq(reply.retcode, 0, name .. " retcode")
  end
end)

H.test("3.3 frame CRC is verified", function()
  local m = F.unpack(X.v33_control)
  H.truthy(m.check_ok)
  local broken = X.v33_control:sub(1, 30) .. "X" .. X.v33_control:sub(32)
  H.eq(F.unpack(broken).check_ok, false)
end)

-- 3.4 ------------------------------------------------------------------------

H.test("3.4 handshake sends tinytuya's frames and derives its session key", function()
  fake.fix_randomness()
  local io = reader(X.v34_resp)
  local key, err, proven = v34.handshake(io, X.local_key)
  H.eq(err, nil)
  H.eq(proven, true)
  H.eq(io.sent[1], X.v34_start, "START frame")
  H.eq(io.sent[2], X.v34_finish, "FINISH frame")
  H.eq(key, X.v34_session_key, "session key")
end)

H.test("3.4 handshake reports a wrong local key", function()
  fake.fix_randomness()
  local key, err = v34.handshake(reader(X.v34_resp), "fedcba9876543210")
  H.eq(key, nil)
  H.truthy(err:find("HMAC"), err)
end)

H.test("3.4 query and control frames match tinytuya", function()
  H.eq(v34.encode(P.COMMAND.DP_QUERY_NEW, 3, "{}", X.v34_session_key), X.v34_query)
  H.eq(v34.encode(P.COMMAND.CONTROL_NEW, 4, X.v34_control_plain, X.v34_session_key), X.v34_control)
end)

H.test("3.4 decodes replies and pushes with the session key", function()
  local reply = assert(v34.read(reader(X.v34_reply), X.v34_session_key))
  H.eq(reply.text, X.status_json)
  local push = assert(v34.read(reader(X.v34_push), X.v34_session_key))
  H.eq(push.text, X.status_json, "push with encrypted version header")
end)

H.test("3.4 rejects a frame whose HMAC does not verify", function()
  local reply, err = v34.read(reader(X.v34_reply), X.local_key)
  H.eq(reply, nil)
  H.truthy(err:find("HMAC"))
end)

-- 3.5 ------------------------------------------------------------------------

H.test("3.5 handshake sends tinytuya's frames and derives its session key", function()
  fake.fix_randomness()
  local io = reader(X.v35_resp)
  -- tinytuya numbered START 1 and FINISH 2.
  local key, err, proven = v35.handshake(io, X.local_key)
  H.eq(err, nil)
  H.eq(proven, true)
  H.eq(io.sent[1], X.v35_start, "START frame")
  H.eq(io.sent[2], X.v35_finish, "FINISH frame")
  H.eq(key, X.v35_session_key, "session key")
end)

H.test("3.5 query and control frames match tinytuya", function()
  fake.fix_randomness()
  H.eq(v35.encode(P.COMMAND.DP_QUERY_NEW, 3, "{}", X.v35_session_key), X.v35_query)
  H.eq(v35.encode(P.COMMAND.CONTROL_NEW, 4, X.v34_control_plain, X.v35_session_key), X.v35_control)
end)

H.test("3.5 decodes a reply and strips the retcode", function()
  local reply = assert(v35.read(reader(X.v35_reply), X.v35_session_key))
  H.eq(reply.text, X.status_json)
  H.eq(reply.retcode, 0)
end)

-- Payloads -------------------------------------------------------------------

H.test("payload decode finds dps at the top level and under data", function()
  H.eq(P.decode('{"dps":{"1":true}}').dps["1"], true)
  H.eq(P.decode('{"protocol":4,"data":{"dps":{"3":2}}}').dps["3"], 2)
  H.same(P.decode(""), {})
  local parsed, raw = P.decode("not json")
  H.eq(parsed, nil)
  H.eq(raw, "not json")
end)

H.test("DP ids are encoded as JSON object keys", function()
  local text = P.encode({dps = P.encode_dps({[1] = true, [3] = 2})})
  H.truthy(text:find('"1":true', 1, true), text)
  H.truthy(text:find('"3":2', 1, true), text)
end)

H.done("test_protocol")
